export function binaryTreeZigzagLevelOrderTraversal(values                 )             {
                                       function build(a                )        {if(!a.length||a[0]===null)return null;const root  ={v:a[0],l:null,r:null},q    =[root];let i=1;for(let j=0;j<q.length&&i<a.length;j++){for(const key of ['l','r']         ){const v=a[i++];if(v!==null&&v!==undefined){const n  ={v,l:null,r:null};q[j][key]=n;q.push(n);}}}return root;}let q    =build(values)?[build(values) ]:[];const out           =[];while(q.length){const row=q.map(n=>n.v);out.push(out.length%2?row.reverse():row);const next    =[];for(const n of q){if(n.l)next.push(n.l);if(n.r)next.push(n.r);}q=next;}return out;
}

